import{_ as t,o as i,c as a,ag as n}from"./chunks/framework.CZxGLIO_.js";const h=JSON.parse('{"title":"Initial administration","description":"Configure site information, email, categories, permissions and third-party login.","frontmatter":{"title":"Initial administration","description":"Configure site information, email, categories, permissions and third-party login."},"headers":[],"relativePath":"en/docs/gooseforum/administration/index.md","filePath":"en/docs/gooseforum/administration/index.md"}'),o={name:"en/docs/gooseforum/administration/index.md"};function r(s,e,d,c,l,g){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="initial-administration" tabindex="-1">Initial administration <a class="header-anchor" href="#initial-administration" aria-label="Permalink to &quot;Initial administration&quot;">​</a></h1><p>After <a href="./../installation/">first startup</a>, sign in as administrator. Set the site&#39;s identity and access rules before opening registration.</p><h2 id="site-information-and-announcements" tabindex="-1">Site information and announcements <a class="header-anchor" href="#site-information-and-announcements" aria-label="Permalink to &quot;Site information and announcements&quot;">​</a></h2><p>In Settings → Site information (<code>/admin/settings/site-info</code>), maintain the name, public URL, contact email, logo, description and external links. Keep the public URL consistent with the real domain and <code>server.url</code> in <code>config.toml</code>.</p><p>Settings → Announcement controls the site announcement. Settings → Posting controls title/body lengths, new-user cooldowns, daily topic limits, attachment enablement, counts, sizes and extensions. Verify these settings with an ordinary account as well as an administrator account.</p><h2 id="test-email-before-requiring-verification" tabindex="-1">Test email before requiring verification <a class="header-anchor" href="#test-email-before-requiring-verification" aria-label="Permalink to &quot;Test email before requiring verification&quot;">​</a></h2><ol><li>In Settings → Mail (<code>/admin/settings/mail</code>), enter the SMTP host, port, credentials, SSL and sender information.</li><li>Send a test and confirm delivery. Testing uses the current form, including unsaved values: save the configuration afterward.</li><li>In Settings → Security, configure registration, email verification and allowed email domains.</li><li>Use a new email address to test registration, verification, login and password reset.</li></ol><p>Creating a new account that requires local email verification is rejected if SMTP is not configured. SMTP acceptance does not guarantee delivery: check spam folders, delivery records and bounces too.</p><h2 id="categories-and-permissions" tabindex="-1">Categories and permissions <a class="header-anchor" href="#categories-and-permissions" aria-label="Permalink to &quot;Categories and permissions&quot;">​</a></h2><p>Create categories at <code>/admin/categories</code>, including names, slugs, descriptions, colors and ordering. Public visibility is derived from read access for the <code>everyone</code> group. Restricted categories need explicit permitted groups.</p><table tabindex="0"><thead><tr><th>Administration task</th><th>Entry point</th><th>What to verify</th></tr></thead><tbody><tr><td>Category content and moderators</td><td>Category management</td><td>Look up moderators by username or user ID</td></tr><tr><td>Category visibility</td><td>Category access settings</td><td>Keep an enabled group with read access; test as guest and ordinary user</td></tr><tr><td>Admin capabilities</td><td><code>/admin/roles</code></td><td>Assign permissions according to duties</td></tr><tr><td>Posting and attachment limits</td><td><code>/admin/settings/posting</code></td><td>Check behavior for new and ordinary users</td></tr></tbody></table><p>A topics manager can edit categories and moderators. A role manager can change category access without automatically receiving category-edit permissions. Converting a public category to restricted can be blocked while multi-category topics exist. Resolve those associations before treating the change as applied.</p><h2 id="third-party-login-and-the-oidc-provider" tabindex="-1">Third-party login and the OIDC provider <a class="header-anchor" href="#third-party-login-and-the-oidc-provider" aria-label="Permalink to &quot;Third-party login and the OIDC provider&quot;">​</a></h2><p>The two settings pages serve different purposes:</p><ul><li><strong>OAuth login</strong> (<code>/admin/settings/oauth</code>): users sign into GooseForum with GitHub, Google, Discord or a custom OIDC identity provider.</li><li><strong>OIDC provider</strong> (<code>/admin/settings/oidc-provider</code>): other applications use GooseForum accounts for login.</li></ul><p>For third-party login, copy the callback URL displayed by the admin page into the identity provider&#39;s console, then configure the Client ID and Secret and enable the provider. Recheck callbacks after changing the domain or HTTPS setup; do not guess the path.</p><p>A third-party email that conflicts with an existing account is not linked automatically. Existing users should sign into their original account and explicitly link the provider. Closing registration still permits existing users to sign in and link identities, but blocks new third-party accounts according to the registration policy.</p><h2 id="before-opening-the-site" tabindex="-1">Before opening the site <a class="header-anchor" href="#before-opening-the-site" aria-label="Permalink to &quot;Before opening the site&quot;">​</a></h2><p>Check guest, ordinary-user and administrator views: category visibility, registration and verification, login/logout, topics/replies, attachments, reporting and management access. Test email links and third-party callbacks using the real HTTPS domain.</p><p>Continue with <a href="./../security/">account security</a> and <a href="./../maintenance/">backup and upgrades</a>.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-mail-security.md" target="_blank" rel="noreferrer">Mail settings</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-categories.md" target="_blank" rel="noreferrer">Category permissions</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-oauth-oidc.md" target="_blank" rel="noreferrer">OAuth / OIDC</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">Registration</a>。</p>',22)])])}const p=t(o,[["render",r]]);export{h as __pageData,p as default};
